<script setup lang="ts">
import { computed } from 'vue'

const props = defineProps<{
  protocol: string
  size?: string
  // When set, overrides the protocol's brand color. Use 'white' for
  // rendering over a solid dark/blue button background where the brand
  // color would wash out. Default is undefined = keep brand color.
  tint?: string
}>()

const sizeClass = computed(() => {
  switch (props.size) {
    case 'xs': return 'w-3 h-3'
    case 'sm': return 'w-4 h-4'
    case 'lg': return 'w-6 h-6'
    case 'xl': return 'w-8 h-8'
    case '2xl': return 'w-10 h-10'
    case '3xl': return 'w-12 h-12'
    case '4xl': return 'w-14 h-14'
    default: return 'w-5 h-5' // md
  }
})

function fillColor(brand: string): string {
  return props.tint || brand
}
</script>
